/* Seasonal windows, from the app's theme_data.html */
(function () {
const SEASONAL_FIXED = {
    valentines:    [[1,15],[3,15]],
    stpatricks:    [[2,15],[4,16]],
    fourthofjuly:  [[6,4],[8,3]],
    halloween:     [[10,1],[11,30]],
    thanksgiving:  [[11,1],[12,25]],
    christmas:     [[11,25],[1,24]],
    newyear:       [[12,2],[1,31]],
    lunarnewyear:  [[1,15],[3,15]],
    carnival:      [[1,15],[3,15]],
    nowruz:        [[3,1],[4,20]],
    pride:         [[6,1],[6,30]],
    midsummer:     [[6,10],[7,10]],
    dayofthedead:  [[10,15],[11,15]],
    midautumn:     [[8,25],[10,15]],
    oktoberfest:   [[9,1],[10,20]],
    kwanzaa:       [[12,20],[1,10]],
    threekingsday: [[12,7],[2,5]],
    songkran:      [[3,14],[5,15]],
    juneteenth:    [[5,20],[7,19]],
    bastilleday:   [[6,14],[8,13]],
    vaisakhi:      [[3,14],[5,14]],
    obon:          [[7,14],[9,15]],
    hanami:        [[3,20],[5,5]],
};
// Variable: the holiday date per year; shown from 30 days before to 30 days after.
const SEASONAL_VARIABLE = {
    easter:   {2025:[4,20],2026:[4,5],2027:[3,28],2028:[4,16],2029:[4,1],2030:[4,21]},
    diwali:   {2025:[10,20],2026:[11,8],2027:[10,29],2028:[10,17],2029:[11,5],2030:[10,26]},
    hanukkah: {2025:[12,14],2026:[12,4],2027:[12,24],2028:[12,12],2029:[12,1],2030:[12,20]},
    eid:      {2025:[3,30],2026:[3,20],2027:[3,9],2028:[2,27],2029:[2,15],2030:[2,4]},
    vesak:    {2025:[5,12],2026:[5,1],2027:[5,20],2028:[5,8],2029:[5,27],2030:[5,17]},
    qingming: {2025:[4,4],2026:[4,5],2027:[4,5],2028:[4,4],2029:[4,4],2030:[4,5]},
    velvetrose: {2025:[5,11],2026:[5,10],2027:[5,9],2028:[5,14],2029:[5,13],2030:[5,12]},
};
// The set of seasonal theme keys whose window contains `now`.
function seasonalVisibleKeys(now = new Date()) {
  const y = now.getFullYear();
  const doy = (mm,dd) => mm*100+dd;
  const cur = doy(now.getMonth()+1, now.getDate());
  const inRange = (s,e) => doy(s[0],s[1]) <= doy(e[0],e[1])
    ? cur >= doy(s[0],s[1]) && cur <= doy(e[0],e[1])
    : cur >= doy(s[0],s[1]) || cur <= doy(e[0],e[1]);
  const visible = new Set();
  Object.entries(SEASONAL_FIXED).forEach(([key,win]) => { if (inRange(win[0],win[1])) visible.add(key); });
  // Variable holidays use real dates: this year's (the last known date once the table runs out) and last
  // year's, so a window that runs past New Year (Hanukkah) is not cut short or borrowed from the wrong year.
  const today = new Date(y, now.getMonth(), now.getDate());
  const daysFrom = (Y,mm,dd) => Math.round((today - new Date(Y,mm-1,dd)) / 86400000);
  Object.entries(SEASONAL_VARIABLE).forEach(([key,dates]) => {
    if ([[y-1, dates[y-1]], [y, dates[y] || dates[y-1]]].some(([Y,b]) => b && Math.abs(daysFrom(Y,b[0],b[1])) <= 30)) visible.add(key);
  });
  return visible;
}
window.TP_DATA.seasonalVisibleKeys = seasonalVisibleKeys;
})();
/* Theme Creator color math (js/_creator.html) and the theme variable check (theme_validator.html) */
(function () {
const _TV_COLOR = /^(#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})|rgba?\([0-9.,\s%/-]*\)|hsla?\([0-9.,\s%/deg-]*\)|transparent|currentColor)$/i;
const _TV_LEN   = /^-?(\d+\.?\d*|\.\d+)(px|em|rem|%)?$/i;
// Reject breakout chars ({}<>;"'`\) AND fetching CSS functions. Parens are allowed
// (rgb()/hsl()/box-shadow need them); only the dangerous *named* functions are blocked.
const _TV_FORBIDDEN = /url\s*\(|image-set\s*\(|image\s*\(|expression\s*\(|-moz-binding|[{}<>;"'`\\]/i;

function _tvShadowOk(v) {
  // box-shadow: comma-separated layers of [inset]? <length>{2,4} <color>?. Strip color
  // functions first (they contain commas) so layers split on the real top-level commas.
  const stripped = v.replace(/(rgba?|hsla?)\([^)]*\)/gi, 'C');
  return stripped.split(',').every(layer => {
    const toks = layer.trim().split(/\s+/).filter(Boolean);
    return toks.length > 0 && toks.every(t =>
      t === 'inset' || t === 'C' || _TV_LEN.test(t) ||
      /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(t) ||
      /^(transparent|currentColor|[a-z]{3,20})$/i.test(t));
  });
}

const THEME_VAR_TYPES = {
  '--bg':'color', '--surf':'color', '--surf2':'color', '--surf3':'color',
  '--border':'color', '--border2':'color', '--acc':'color', '--acc-h':'color', '--acc-dim':'color',
  '--text':'color', '--text2':'color', '--muted':'color', '--red':'color',
  '--shadow':'shadow', '--thumb-bg':'color', '--log-bg':'color', '--log-text':'color',
  '--modal-overlay':'color', '--modal-shadow':'shadow',
  '--btn-primary-text':'color', '--btn-on-accent':'color', '--btn-red-border':'color',
  '--audio-btn-color':'color', '--dur-bg':'color', '--dur-text':'color',
};

function validateThemeVar(name, value) {
  if (typeof value !== 'string' || value.length === 0 || value.length > 200) return false;
  if (_TV_FORBIDDEN.test(value)) return false;
  const t = THEME_VAR_TYPES[name];
  if (!t) return false;                       // unknown var → reject (allowlist)
  const v = value.trim();
  if (t === 'color')  return _TV_COLOR.test(v);
  if (t === 'shadow') return _tvShadowOk(v);
  return false;
}
  const CORE_KEYS     = ['--bg','--surf','--surf2','--surf3','--acc','--acc-h','--text','--text2','--border','--red'];
  const CORE_DEFAULTS = { '--bg':'#0b1120','--surf':'#111c2e','--surf2':'#182338','--surf3':'#1f2f47',
                          '--acc':'#3b82f6','--acc-h':'#60a5fa',
                          '--text':'#e2e8f6','--text2':'#8faecf','--border':'#243454','--red':'#ef4444' };
  function hexToRgb(h) {
    h = String(h).trim().replace('#','');
    if (h.length === 3) h = h.split('').map(c => c + c).join('');
    const n = parseInt(h, 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  function clampByte(n) { return Math.max(0, Math.min(255, Math.round(n))); }
  function rgbToHex(rgb) { return '#' + rgb.map(c => clampByte(c).toString(16).padStart(2,'0')).join(''); }
  function relLum(rgb) { return (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255; }
  function mix(a, b, t) { const A = hexToRgb(a), B = hexToRgb(b); return rgbToHex([0,1,2].map(i => A[i] + (B[i] - A[i]) * t)); }
  function toHex6(v) {
    const m = String(v).trim().match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (!m) return null;
    let h = m[1];
    if (h.length === 3) h = h.split('').map(c => c + c).join('');
    return '#' + h.toLowerCase();
  }

  // Full 25-var theme map from the 10 core (core last so user picks win).
  function deriveAll(core) {
    const acc = core['--acc'];
    const [ar, ag, ab] = hexToRgb(acc);
    const onAcc = relLum(hexToRgb(acc)) > 0.6 ? '#000000' : '#ffffff';
    return Object.assign({}, {
      '--surf3':            mix(core['--surf2'], core['--text'], 0.06),
      '--border2':          mix(core['--border'], core['--text'], 0.20),
      '--acc-h':            mix(acc, '#ffffff', 0.18),
      '--acc-dim':          `rgba(${ar},${ag},${ab},0.14)`,
      '--muted':            mix(core['--text2'], core['--bg'], 0.35),
      '--shadow':           '0 4px 32px rgba(0,0,0,0.6)',
      '--thumb-bg':         mix(core['--bg'], '#000000', 0.25),
      '--log-bg':           mix(core['--bg'], '#000000', 0.35),
      '--log-text':         core['--text2'],
      '--modal-overlay':    'rgba(0,0,0,0.75)',
      '--modal-shadow':     '0 20px 60px rgba(0,0,0,0.8)',
      '--btn-primary-text': onAcc,
      '--btn-on-accent':    onAcc,
      '--btn-red-border':   mix(core['--red'], '#000000', 0.55),
      '--audio-btn-color':  acc,
      '--dur-bg':           'rgba(0,0,0,0.85)',
      '--dur-text':         core['--text'],
    }, core);
  }
  function validPairs(map) {
    const out = {};
    for (const [k, v] of Object.entries(map)) if (validateThemeVar(k, v)) out[k] = v;
    return out;
  }
window.TP_DATA.creator = { CORE_KEYS: CORE_KEYS, CORE_DEFAULTS: CORE_DEFAULTS, hexToRgb: hexToRgb, relLum: relLum, mix: mix,
  toHex6: toHex6, deriveAll: deriveAll, validPairs: validPairs, validateThemeVar: validateThemeVar };
})();
